{
  "components": [
    {
      "type": "claim",
      "quote": "The support group assesses the proposed corridors and recommends a planning corridor to the SFOE, together with the type of transmission technology to be used (overhead lines or underground cables).",
      "gist": "Support group evaluates corridors and recommends a planning corridor and transmission technology to SFOE."
    },
    {
      "type": "claim",
      "quote": "In its assessment it takes the spatial and environmental impacts into account, as well as technical aspects and the question of economic viability.",
      "gist": "Assessment considers spatial, environmental, technical, and economic factors."
    },
    {
      "type": "obligation",
      "quote": "the SFOE prepares a draft version of the detailed plan and initiates the consultation and participation procedure in the cantons",
      "gist": "SFOE prepares draft plan and starts consultation in cantons."
    },
    {
      "type": "obligation",
      "quote": "The SFOE then finalises the detailed plan and initiates a consultation of public authorities.",
      "gist": "SFOE finalises plan and consults public authorities."
    },
    {
      "type": "entity",
      "quote": "SFOE",
      "gist": "Swiss Federal Office of Energy (inferred from context)"
    },
    {
      "type": "entity",
      "quote": "support group",
      "gist": "An advisory or evaluation group for transmission corridors"
    }
  ]
}
